{"code": "from PIL import Image
import os

data_dir = 'data_small/CovidDataset_70_30'
file_paths = []

# Collect some sample file paths
for split in ['Train', 'Test', 'Validation']:
    for class_dir in ['Normal', 'Covid']:
        split_path = os.path.join(data_dir, split, class_dir)
        if os.path.exists(split_path):
            for file in os.listdir(split_path)[:2]:  # Check first 2 files
                file_paths.append(os.path.join(split_path, file))

print("Checking files:")
for fp in file_paths:
    try:
        img = Image.open(fp)
        print(f"✓ {fp}: Valid image, size={img.size}")
        img.close()
    except Exception as e:
        print(f"✗ {fp}: ERROR - {e}")"}

