{"code": "from PIL import Image

data_dir = 'data_small/CovidDataset_70_30'

# Verify images are valid
count = 0
for split in ['Train', 'Test', 'Validation']:
    for class_dir in ['Normal', 'Covid']:
        split_path = os.path.join(data_dir, split, class_dir)
        if os.path.exists(split_path):
            for file in os.listdir(split_path):
                fp = os.path.join(split_path, file)
                try:
                    img = Image.open(fp)
                    count += 1
                    img.close()
                except Exception as e:
                    print(f"✗ {fp}: ERROR - {e}")

print(f"Verified {count} valid images")"}

